72	func (s *RSSService) GetExploreRSS(c *echo.Context) error {
73		ctx := c.Request().Context()
74		cacheKey := "explore"
75	
76		// Check cache first
77		if cached := s.getFromCache(cacheKey); cached != nil {
78			// Check ETag for conditional request
79			if c.Request().Header.Get("If-None-Match") == cached.etag {
80				return c.NoContent(http.StatusNotModified)
81			}
82			s.setRSSHeaders(c, cached.etag, cached.lastModified)
83			return c.String(http.StatusOK, cached.content)
84		}
85	
86		normalStatus := store.Normal
87		limit := maxRSSItemCount
88		memoFind := store.FindMemo{
89			RowStatus:       &normalStatus,
90			VisibilityList:  []store.Visibility{store.Public},
91			ExcludeComments: true,
92			Limit:           &limit,
93		}
94		memoList, err := s.Store.ListMemos(ctx, &memoFind)
95		if err != nil {
96			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to find memo list").Wrap(err)
97		}
98	
99		baseURL := c.Scheme() + "://" + c.Request().Host
100		rss, lastModified, err := s.generateRSSFromMemoList(ctx, memoList, baseURL, nil)
101		if err != nil {
102			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to generate rss").Wrap(err)
103		}
104	
105		// Cache the result
106		etag := s.putInCache(cacheKey, rss, lastModified)
107		s.setRSSHeaders(c, etag, lastModified)
108		return c.String(http.StatusOK, rss)
109	}
